/**
 * Every character and object sprite in the game: 16-bit style pixel art, generated by the art scripts
 * (shaded ramps, coloured outlines, dithering) and stored here as a palette plus one or two characters per pixel.
 * The floor scenes themselves are bitmaps in res/drawable-nodpi.
 */
object Art {
    private const val ALPHA = ".!#%&'()*+,-/0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{|}~"

    /** Decodes a sprite: [k] characters per pixel, each an index into [pal] (8 hex digits, ARGB, per colour); 0 is clear. */
    private fun dec(w: Int, h: Int, k: Int, pal: String, data: String): Sprite {
        val colors = Array(pal.length / 8) { i -> Color(pal.substring(i * 8, i * 8 + 8).toLong(16).toInt()) }
        val n = ALPHA.length
        val cells = Array<Color?>(w * h) { i ->
            val v = if (k == 1) ALPHA.indexOf(data[i]) else ALPHA.indexOf(data[i * 2]) * n + ALPHA.indexOf(data[i * 2 + 1])
            if (v == 0) null else colors[v - 1]
        }
        return Sprite(w, h, cells)
    }

