    private val asleep = HashMap<HelperKind, Sprite>()

    /** A helper; [frame] 0..3 cycles rest, lift, rest, blink (0 and 1 alone make a bob). */
    fun helper(kind: HelperKind, frame: Int = 0): Sprite = helpers.getValue(kind)[frame and 3]

    /** A helper still asleep: greyed out, cached. */
    fun helperAsleep(kind: HelperKind): Sprite = asleep.getOrPut(kind) { helper(kind, 3).muted() }

    /** A mischievous imp; [frame] 0 or 1. */
    fun imp(frame: Int = 0): Sprite = imps[frame and 1]

    fun decor(kind: DecorKind): Sprite = decors.getValue(kind)[0]

    /** A decor item's animation frame (candles flicker, the cat blinks); still items have one frame. */
    fun decor(kind: DecorKind, frame: Int): Sprite = decors.getValue(kind).let { it[Math.floorMod(frame, it.size)] }

    /** The old master, for his letters; frame 1 blinks. */
    fun master(frame: Int = 0): Sprite = masters[frame and 1]

    /** The apprentice (the user). */
    fun apprentice(frame: Int = 0): Sprite = apprentices[frame and 1]

    /** A candle flame, three frames. */
    fun flame(frame: Int): Sprite = flames[Math.floorMod(frame, flames.size)]

    /** A puff of rising steam, four frames. */
    fun steam(frame: Int): Sprite = steams[Math.floorMod(frame, steams.size)]

    val moon: Sprite get() = extras.getValue("moon")
    val cloud: Sprite get() = extras.getValue("cloud")
    val cobweb: Sprite get() = extras.getValue("cobweb")

    /** A furnishing that tells a floor's kind at a glance (the full rooms are scene bitmaps). */
    fun prop(kind: FloorKind): Sprite = when (kind) {
        FloorKind.KITCHEN -> decor(DecorKind.CAULDRON)
        FloorKind.LIVING -> decor(DecorKind.BOOKS)
        FloorKind.BEDROOM -> decor(DecorKind.TELESCOPE)
        FloorKind.BATH -> helper(HelperKind.BUCKET)
        FloorKind.HALL -> decor(DecorKind.LANTERN)
        FloorKind.BALCONY -> decor(DecorKind.FERN)
        FloorKind.KIDS -> decor(DecorKind.RUG)
        FloorKind.STUDY -> decor(DecorKind.CANDLES)
        FloorKind.LAUNDRY -> helper(HelperKind.BASKET)
        FloorKind.PETS -> decor(DecorKind.CAT)
        FloorKind.WHOLE -> decor(DecorKind.FIREPLACE)
    }

    /** Every sprite, for tests and previews. */
    fun all(): List<Sprite> =
        HelperKind.entries.flatMap { k -> (0..3).map { helper(k, it) } } +
            listOf(imp(0), imp(1), master(0), master(1), apprentice(0), apprentice(1), moon, cloud, cobweb) +
            DecorKind.entries.flatMap { k -> decors.getValue(k).toList() } + (0..2).map { flame(it) } + (0..3).map { steam(it) }
}
